 q.emulate_media(reduced_motion='no-preference');q.clock.set_system_time(datetime(2026,10,30,6,0,tzinfo=timezone.utc));q.evaluate('window.dispatchEvent(new Event("focus"))');q.wait_for_function('state.notifications.items.some(n=>n.id==="streak:2026-10-30")');assert q.locator('#notificationsToggle svg').evaluate('(e)=>getComputedStyle(e).animationName')=='notification-ring';q.locator('#languageToggle').click();assert q.locator('#languagePanel').evaluate('(e)=>getComputedStyle(e).animationName')=='header-panel-in';q.keyboard.press('Escape');q.emulate_media(reduced_motion='reduce')
 q.goto(BASE+'#home');q.locator('#notificationsToggle').click();q.locator('[data-notice-read-all]').click();assert q.locator('.notice-count').is_hidden();q.reload();assert q.locator('.notice-count').is_hidden();assert not errors,errors
